package com.bankpli.javabank.credit;import java.time.Duration;import java.util.*;import java.util.function.Supplier;import org.springframework.web.bind.annotation.*;
@RestController @RequestMapping("/api/credit")public class CreditController{private final CreditScoringService scoring;private final RiskDecisionService decisions;public CreditController(CreditScoringService s,RiskDecisionService d){scoring=s;decisions=d;}public record Request(List<Integer>bureauScores,List<Integer>history){}@PostMapping("/score")public CreditScoringService.Result score(@RequestBody Request r){if(r.bureauScores()==null||r.bureauScores().size()!=5)throw new IllegalArgumentException("Five scores are required");List<Supplier<Integer>>tasks=r.bureauScores().stream().<Supplier<Integer>>map(v->()->v).toList();return scoring.score(tasks,Duration.ofSeconds(2),r.history());}@GetMapping("/decision/{score}")public Map<String,Object>decision(@PathVariable int score){return Map.of("score",score,"decision",decisions.decide(score));}}
